\deleted{\unsure{We shall be able to|We set}} \inserted{We set}
\[
\mathbb E\ell_1\deleted{(\unsure{S})}\simeq\mathbb C/\mathbb Z[\zeta]
\]
\[
\mathbb E\ell_1(S)\simeq\mathbb E\ell_1\mathbin{\wedge}_{\mathbb Z/6\mathbb Z}S
\]

\uline{Construction} We realize the combinatorial hexagon $S$ \unsure{Euclideanly} (canonical), \unsure{in} Euclidean \unsure{vector space} $V_S$, \deleted{\unsure{centre}} \inserted{origin} being the barycentre of $S$. We denote by $V_S$ the \deleted{\unsure{lattice}} \inserted{lattice} generated by $S$, and
\[
X_S=\mathbb E\ell_1(S)\simeq V_S/\Gamma_S
\]
The \uline{oriented} Euclidean structure of $V_S$ defines the complex structure of $X_S$.

